const INBOX_TYPES=['Owner','Trade request','Trade proposal','Trade block','All-Star','Watch list','Morale'];
let inboxFilter='All',inboxOpen=null;
function inboxStore(){if(!state.gmInbox)state.gmInbox={nextId:1,items:[],lastProposal:''};return state.gmInbox}
function addGMMessage(type,sender,subject,body,proposal=null){const box=inboxStore();box.items.unshift({id:box.nextId++,year:state.year,day:state.day,type,sender,subject,body,read:false,proposal,status:'open'});box.items=box.items.slice(0,500)}
function ensureInboxWelcome(){const box=inboxStore();if(!box.items.some(m=>m.type==='Owner'&&m.year===state.year)){const owner=ownerFor(team());addGMMessage('Owner','Team ownership','Your season priorities',`Welcome, ${state.gmName||'General Manager'}. ${OWNER_TYPES[owner.type].description} Review your ownership goals in GM Office. Current owner patience: ${owner.patience}%.`)}}
function gmInboxUnread(){ensureInboxWelcome();return inboxStore().items.filter(m=>!m.read).length}
function openGMInbox(){ensureInboxWelcome();inboxOpen=null;go('GM Inbox')}
function openGMMessage(id){const m=inboxStore().items.find(m=>m.id===id);if(!m)return;m.read=true;inboxOpen=id;save();render()}
function markGMInboxRead(){inboxStore().items.forEach(m=>m.read=true);save();render()}
function proposalAvailable(m){if(!m.proposal||m.status!=='open'||m.year!==state.year||state.day>m.day+7||tradeDeadlinePassed())return false;const p=m.proposal;return team().roster.some(x=>x.id===p.out)&&state.teams[p.club]?.roster.some(x=>x.id===p.into)}
function reviewGMProposal(id){const m=inboxStore().items.find(m=>m.id===id);if(!m||!proposalAvailable(m))return toast('This proposal is no longer available.');go('Trades');document.getElementById('out').value=m.proposal.out;document.getElementById('into').value=m.proposal.into;toast('Proposal loaded. Review the players and submit through the Trade Desk.')}
function declineGMProposal(id){const m=inboxStore().items.find(m=>m.id===id);if(!m)return;m.status='declined';m.read=true;save();render()}
function gmInboxView(){ensureInboxWelcome();const messages=inboxStore().items.filter(m=>inboxFilter==='All'||inboxFilter==='Unread'&&!m.read||m.type===inboxFilter);return `<section class="panel"><div class="panelhead"><h2>Private messages</h2><div class="actions"><button type="button" onclick="showOwnerWelcome(true)">View owner message</button><button onclick="markGMInboxRead()">Mark all read</button></div></div><nav class="po-tabs" aria-label="Inbox filters">${['All','Unread',...INBOX_TYPES].map(t=>`<button class="${inboxFilter===t?'selected':''}" onclick="inboxFilter='${t}';render()">${t}</button>`).join('')}</nav><div class="gm-inbox-list">${messages.map(m=>`<article class="gm-message ${m.read?'':'is-unread'}"><button class="gm-message-heading" aria-expanded="${inboxOpen===m.id}" onclick="openGMMessage(${m.id})"><span><small>${escapeHTML(m.sender)} · ${m.type} · ${m.year} season, day ${m.day+1}</small><strong>${m.read?'':'● '}${escapeHTML(m.subject)}</strong></span><span>${m.read?'Read':'Unread'}</span></button>${inboxOpen===m.id?`<div class="gm-message-body"><p>${escapeHTML(m.body)}</p><div class="actions">${m.type==='Owner'?'<button onclick="go(\'GM Office\')">View ownership goals</button>':m.type==='Trade request'?'<button onclick="go(\'Roster\')">Manage roster</button><button onclick="go(\'Trades\')">Trade desk</button>':m.type==='Morale'?'<button onclick="go(\'Roster\')">View locker room</button>':m.type==='Watch list'?'<button onclick="go(\'Watch list\')">View watch list</button>':m.type==='All-Star'?'<button onclick="showAllStarWeekend()">All-Star voting</button>':m.type==='Trade block'?'<button onclick="openTradeBlock()">View trade block</button>':proposalAvailable(m)?`<button class="primary" onclick="reviewGMProposal(${m.id})">Review proposal</button><button onclick="declineGMProposal(${m.id})">Decline</button>`:`<span>${m.status==='declined'?'Declined':'Proposal expired or players unavailable'}</span>`}</div></div>`:''}</article>`).join('')||'<p class="note">No messages in this view.</p>'}</div></section>`}
const inboxSayBefore=say;say=function(text){inboxSayBefore(text);if(/^OWNER (REVIEW|UPDATE|LONG-TERM REVIEW):/.test(text))addGMMessage('Owner','Team ownership','Ownership update',text);else if(text.includes('('+team().abbr+')')&&/requests a trade|withdraws their trade request/.test(text))addGMMessage('Trade request',text.split(' (')[0],/withdraws/.test(text)?'Trade request withdrawn':'Player requests a trade',text)};
const inboxOwnerDayBefore=ownerDay;ownerDay=function(...args){const result=inboxOwnerDayBefore(...args);generateGMProposal();return result};
function generateGMProposal(){if(state.day<1||state.day%7!==0||tradeDeadlinePassed()||!ownerCanManage())return;const box=inboxStore(),key=state.year+':'+state.day;if(box.lastProposal===key)return;box.lastProposal=key;const clubs=state.teams.filter(t=>t.id!==controlledTeamId()).filter(t=>!expansionPendingSeason(t));for(let n=0;n<clubs.length;n++){const club=clubs[(Math.floor(state.day/7)+n)%clubs.length];for(const incoming of club.roster){const outgoing=team().roster.find(p=>Math.abs(p.ovr-incoming.ovr)<=3&&Math.abs(p.salary-incoming.salary)<=5&&coachTradeValue(p,club)>=coachTradeValue(incoming,club)-1&&payroll()-p.salary+incoming.salary<=financeRosterLimit()&&ownerPayroll(club)-incoming.salary+p.salary<=financeRosterLimit(club));if(!outgoing)continue;addGMMessage('Trade proposal',gmDisplayName(club)+', '+club.city+' GM','Trade proposal from '+club.city,`We offer ${incoming.name} (${incoming.pos}, ${incoming.ovr} OVR, ${money(incoming.salary)}) for ${outgoing.name} (${outgoing.pos}, ${outgoing.ovr} OVR, ${money(outgoing.salary)}). Review this one-for-one proposal in the Trade Desk. Available for seven league days, subject to the trade deadline and roster changes.`,{club:club.id,out:outgoing.id,into:incoming.id});return}}}
function readGMInbox(raw,bad,count){if(raw===undefined)return undefined;if(!raw||!Number.isInteger(raw.nextId)||raw.nextId<1||typeof raw.lastProposal!=='string'||raw.lastProposal.length>40||!Array.isArray(raw.items)||raw.items.length>500)bad('invalid GM inbox');const ids=new Set();return {nextId:raw.nextId,lastProposal:raw.lastProposal,items:raw.items.map(m=>{if(!m||!Number.isInteger(m.id)||m.id<1||m.id>=raw.nextId||ids.has(m.id)||!INBOX_TYPES.includes(m.type)||!Number.isInteger(m.year)||m.year<1900||m.year>10000||!Number.isInteger(m.day)||m.day<0||m.day>367||typeof m.read!=='boolean'||!['open','declined'].includes(m.status)||['sender','subject','body'].some(k=>typeof m[k]!=='string'||m[k].length>2000))bad('invalid inbox message');ids.add(m.id);const p=m.proposal;if(p&&(!Number.isInteger(p.club)||p.club<0||p.club>=count||!Number.isInteger(p.out)||!Number.isInteger(p.into)||p.out<0||p.into<0))bad('invalid inbox proposal');return {id:m.id,year:m.year,day:m.day,type:m.type,sender:m.sender,subject:m.subject,body:m.body,read:m.read,status:m.status,proposal:p?{club:p.club,out:p.out,into:p.into}:null}})}}
